Filters['q'] !== '') $activeFilterChips[] = ['key' => 'q', 'label' => 'IP address: ' . $loginHistoryFilters['q']]; if ($loginHistoryFilters['outcome'] !== '') $activeFilterChips[] = ['key' => 'outcome', 'label' => 'Outcome: ' . ($loginHistoryFilters['outcome'] === 'success' ? 'Successful' : 'Unsuccessful')]; if ($loginDatePreset !== '') $activeFilterChips[] = ['key' => 'date_range', 'clear_keys' => ['date_range', 'start_date', 'end_date'], 'label' => 'Date: ' . ['last7' => 'Last 7 days', 'last30' => 'Last 30 days', 'custom' => trim($loginHistoryFilters['start_date'] . ' to ' . $loginHistoryFilters['end_date'])][$loginDatePreset]]; $filterResetUrl = '/account/password?per_page=' . (int) ($loginHistoryPagination['page_size'] ?? 20) . '#login-history-results'; require dirname(__DIR__) . '/partials/active-filter-chips.php'; ?><span class="visually-hidden" role="status" aria-live="polite" data-filter-status></span></form><?php if (($loginHistory ?? []) === []): ?><p class="empty-note">No sign-in attempts match these filters.</p><?php else: ?><div class="table-responsive staff-table-wrap" id="login-history-results" data-pagination-target><table class="table staff-table"><caption class="visually-hidden">Recent sign-in attempts for your account</caption><thead><tr><th scope="col">Result</th><th scope="col">Date and time (UTC)</th><th scope="col">IP address</th></tr></thead><tbody><?php foreach ($loginHistory as $attempt): ?><tr><td><span class="status-pill status-<?= $attempt['was_successful'] ? 'verified' : 'failed' ?>"><?= $attempt['was_successful'] ? 'Successful' : 'Unsuccessful' ?></span></td><td><?= e(date('M j, Y H:i:s', strtotime($attempt['attempted_at'] . ' UTC'))) ?></td><td><?= e($attempt['ip_address'] ?: 'Not recorded') ?></td></tr><?php endforeach; ?></tbody></table></div><?php $pagination = $loginHistoryPagination + ['base_url' => '/account/password', 'query' => [], 'target' => 'login-history-results']; require dirname(__DIR__) . '/partials/pagination.php'; ?><